// n8n node "Check input" (W6). The only thing W6 accepts: one short piece of text.
// The text is used for this one run and is never written anywhere. It is not in the reply either.
const body = $input.first().json.body ?? $input.first().json;
const words = typeof body.words === 'string' ? body.words.replace(/\s+/g, ' ').trim() : '';
if (words.length < 3) throw new Error('Too short');
if (words.length > 280) throw new Error('Too long');
return [{ json: { words } }];

// n8n node "Rules" (W6). The default, and the fallback whenever the AI step is off or its answer is not valid.
// Counts keyword matches per barrier. A tie or no match is never guessed: it says 'unsure' or 'none' with a low confidence.
// English and German keywords, because that is what people will type. Edit the lists here and run the evaluation again.
const WORDS = {
  charging: /charg|wallbox|\bplug|socket|garage|parking|park\b|parked|landlord|tenant|\brent(ed|er)?\b|\bapartment|flat\b|no bay|laden|ladestation|vermieter|mieter|tiefgarage|steckdose/gi,
  cost: /expensive|price|cost|afford|\bcheap|money|\bpay\b|\bloan|\blease|budget|depreciat|resale|\bworth|teuer|preis|kosten|geld|franken|chf/gi,
  trips: /\brange|long (trip|drive|distance)|holiday|vacation|road ?trip|motorway|highway|autobahn|\btow\b|\btrailer|ski\b|mountain|italy|reichweite|ferien|urlaub|anh[aä]nger|strecke/gi,
  trust: /batter|\bfire|lifespan|degrad|winter|\bcold\b|reliab|technolog|\btrust|durab|repair|second-hand|used (ev|electric)|akku|zuverl|vertrau|kälte|kalt/gi,
};
const DOUBT = /not sure|don't know|dont know|no idea|maybe|unsure|dunno|weiss nicht|weiß nicht|keine ahnung|unklar/i;
const { words } = $input.first().json;
const score = Object.fromEntries(Object.entries(WORDS).map(([k, re]) => [k, (words.match(re) || []).length]));
const ranked = Object.entries(score).sort((a, b) => b[1] - a[1]);
const [top, second] = ranked;
let barrier;
let confidence;
if (top[1] === 0) {
  barrier = DOUBT.test(words) ? 'unsure' : 'none';
  confidence = 0.3;
} else if (top[1] === second[1]) {
  barrier = 'unsure';
  confidence = 0.35;
} else {
  barrier = top[0];
  confidence = Math.min(0.9, 0.5 + 0.15 * (top[1] - second[1]));
}
return [{ json: { words, rules: { barrier, confidence: Math.round(confidence * 100) / 100 } } }];

// n8n node "AI flag" (W6). The switch for the AI step. It is false, so the workflow answers from the rules alone.
// To try the AI step: add a chat-model credential to "Chat model", enable that node and "Extract barrier", set ai to true here.
// Do that only after Martin has said yes, and after node scripts/words-eval.mjs has been read.
const ai = false;
return $input.all().map((i) => ({ json: { ...i.json, ai } }));

// n8n node "Decide" (W6). Takes the AI answer only if it is exactly a name on the closed list with a confidence from 0 to 1,
// and at least MIN_CONFIDENCE. Anything else, or a failed AI call, falls back to the rules. The reply carries no text.
const MIN_CONFIDENCE = 0.6;
const BARRIERS = ['charging', 'cost', 'trips', 'trust', 'unsure', 'none'];
const rules = $('Rules').first().json.rules;
let ai = null;
try {
  const out = $('Extract barrier').first().json.output;
  if (out && BARRIERS.includes(out.barrier) && typeof out.confidence === 'number' && out.confidence >= 0 && out.confidence <= 1) ai = out;
} catch (e) {
  ai = null; // the AI step did not run (flag off) or failed
}
const useAi = ai !== null && ai.confidence >= MIN_CONFIDENCE;
const pick = useAi ? ai : rules;
return [{ json: { ok: true, barrier: pick.barrier, confidence: Math.round(pick.confidence * 100) / 100, via: useAi ? 'ai' : 'rules' } }];
